preConditionHook:
// EL: avgBody = Average(AbsValue(close - open), lookback);
//     avgRange = Average(high - low, lookback);
// Average recomputes from scratch every bar (EL_Summation_Probe, 2,808/2,808),
// and both arguments are PRICE expressions with real history back to the chart
// start -- so these are fresh loops over price, NOT the WFSafe_AvgTrueRange
// rolling accumulator and NOT a mirrored variable buffer (contrast
// BarRangeAboveStd, whose Average runs over an EL variable). Summed
// newest-first, EL's Summation order, and divided by the same (int) bound the
// loop uses, as LargeOutsideBar does.
// Scratch locals persist across bars, so both are reset here before the loop.
avgBody = 0.0;
avgRange = 0.0;
for (int i = 0; i < (int)lookback; ++i) {
    avgBody += std::fabs(close[i] - open[i]);
    avgRange += high[i] - low[i];
}
avgBody /= (int)lookback;
avgRange /= (int)lookback;
